<script setup lang="ts">
import {computed,onBeforeUnmount,toRaw} from 'vue'
import type {Transform} from '../shared/contracts'
import {floatingCorners,moveFloatingCorner,resizeFloatingCorner,type FloatingCorners} from '../shared/floating-transform'
const props=defineProps<{transform:Transform;zoom:number;corners?:FloatingCorners}>(),emit=defineEmits<{update:[Transform];corners:[FloatingCorners|undefined]}>()
let drag:{pointer:number;target:HTMLElement;point:[number,number];zoom:number;transform:Transform;corners?:FloatingCorners;originalCorners?:FloatingCorners;index?:number;center:[number,number];mode:'move'|'resize'|'rotate'|'distort'}|undefined
const outline=computed(()=>props.corners??floatingCorners(props.transform))
function start(event:PointerEvent,mode:'move'|'resize'|'rotate',index?:number){if(event.button!==0)return;const target=event.currentTarget as HTMLElement,box=target.closest('.floating-selection')?.getBoundingClientRect(),originalCorners=props.corners?structuredClone(toRaw(props.corners)):undefined,corners=mode==='resize'&&(event.metaKey||event.ctrlKey)||props.corners?structuredClone(toRaw(props.corners??floatingCorners(props.transform))):undefined;drag={pointer:event.pointerId,target,point:[event.clientX,event.clientY],zoom:props.zoom,transform:structuredClone(toRaw(props.transform)),corners,originalCorners,index,center:box?[box.left+box.width/2,box.top+box.height/2]:[event.clientX,event.clientY],mode:corners&&mode==='resize'?'distort':mode};target.setPointerCapture(event.pointerId);if(corners&&!props.corners)emit('corners',corners);event.preventDefault()}
