</script>
<template>
 <svg v-if="corners" class="floating-distort" aria-label="Distort selected pixels" :style="{overflow:'visible'}"><polygon :points="outline.map(p=>`${p[0]*zoom},${p[1]*zoom}`).join(' ')" fill="transparent" stroke="#0a84ff" stroke-width="1.5" @pointerdown.stop="start($event,'move')" @pointermove.stop="move" @pointerup.stop="end()" @pointercancel.stop="end(true)"/></svg>
 <div v-else class="floating-selection" aria-label="Transform selected pixels" :style="{left:`${transform.origin[0]*zoom}px`,top:`${transform.origin[1]*zoom}px`,width:`${transform.size[0]*zoom}px`,height:`${transform.size[1]*zoom}px`,transform:`rotate(${transform.rotation}deg)`}" @pointerdown.stop="start($event,'move')" @pointermove.stop="move" @pointerup.stop="end()" @pointercancel.stop="end(true)"><button class="floating-rotate" aria-label="Rotate selected pixels" @pointerdown.stop="start($event,'rotate')" @pointermove.stop="move" @pointerup.stop="end()" @pointercancel.stop="end(true)"/></div>
 <button v-for="(point,index) in outline" :key="index" class="floating-corner" :aria-label="corners?`Selected pixels corner ${index+1}`:index===2?'Resize selected pixels':`Resize selected pixels corner ${index+1}`" :style="{left:`${point[0]*zoom}px`,top:`${point[1]*zoom}px`,cursor:corners?'crosshair':'nwse-resize'}" title="Drag to resize. Cmd/Ctrl-drag to distort. Shift unlocks the aspect ratio." @pointerdown.stop="start($event,'resize',index)" @pointermove.stop="move" @pointerup.stop="end()" @pointercancel.stop="end(true)"/>
</template>
<style scoped>.floating-selection{position:absolute;z-index:6;box-sizing:border-box;border:1px solid #0a84ff;cursor:move;touch-action:none}.floating-rotate,.floating-corner{position:absolute;width:12px;height:12px;padding:0;background:white;border:1px solid #0a84ff;touch-action:none}.floating-rotate{right:calc(50% - 6px);top:-26px;border-radius:50%;cursor:crosshair}.floating-distort{position:absolute;left:0;top:0;width:1px;height:1px;z-index:6;pointer-events:none}.floating-distort polygon{pointer-events:all;cursor:move;touch-action:none}.floating-corner{z-index:7;transform:translate(-50%,-50%);}</style>
